<?php defined('_JEXEC') or die; use Joomla\CMS\Router\Route; ?>
<div class="row g-4"><div class="col-lg-7"><h1>Categories</h1><table class="table"><thead><tr><th>Title</th><th>Posts</th><th>Status</th></tr></thead><tbody><?php foreach($this->items as $item):?><tr><td><a href="<?php echo Route::_('index.php?option=com_blog&view=categories&category_id='.(int)$item->id);?>"><?php echo htmlspecialchars($item->title,ENT_QUOTES,'UTF-8');?></a></td><td><?php echo(int)$item->post_count;?></td><td><?php echo $item->published?'Published':'Unpublished';?></td></tr><?php endforeach;?></tbody></table></div><div class="col-lg-5"><h2><?php echo $this->item->id?'Edit category':'New category';?></h2><form method="post" action="<?php echo Route::_('index.php?option=com_blog&task=categories.save');?>"><input type="hidden" name="jform[id]" value="<?php echo(int)$this->item->id;?>"><div class="mb-3"><label>Title<input required class="form-control" name="jform[title]" value="<?php echo htmlspecialchars($this->item->title,ENT_QUOTES,'UTF-8');?>"></label></div><div class="mb-3"><label>Alias<input class="form-control" name="jform[alias]" value="<?php echo htmlspecialchars($this->item->alias,ENT_QUOTES,'UTF-8');?>"></label></div><div class="mb-3"><label>Description<textarea class="form-control" name="jform[description]"><?php echo htmlspecialchars($this->item->description,ENT_QUOTES,'UTF-8');?></textarea></label></div><input type="hidden" name="jform[published]" value="1"><input type="hidden" name="jform[access]" value="1"><input type="hidden" name="jform[language]" value="*"><?php echo \Joomla\CMS\HTML\HTMLHelper::_('form.token');?><button class="btn btn-success">Save category</button></form><?php if($this->item->id):?><form class="mt-2" method="post" action="<?php echo Route::_('index.php?option=com_blog&task=categories.delete');?>"><input type="hidden" name="id" value="<?php echo(int)$this->item->id;?>"><?php echo \Joomla\CMS\HTML\HTMLHelper::_('form.token');?><button class="btn btn-danger">Delete</button></form><?php endif;?></div></div>
